import type { Metadata } from "next";
import { localePath, type Lang } from "./index";

/** Preview picture for links shared on WhatsApp / Facebook (generated by src/app/opengraph-image.tsx). */
export const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "Study Point — Kindergarten & English Classes, Point Pedro and Vathiry" };

/** canonical + hreflang links so Google shows the right language to the right visitor, plus the share-preview tags. */
export function pageMeta(lang: Lang, path: string, title: string, description: string): Metadata {
  return {
    title,
    description,
    alternates: {
      canonical: localePath(lang, path),
      languages: { en: localePath("en", path), ta: localePath("ta", path), "x-default": localePath("en", path) },
    },
    openGraph: {
      type: "website",
      siteName: "Study Point",
      url: localePath(lang, path),
      title,
      description,
      locale: lang === "ta" ? "ta_LK" : "en_LK",
      alternateLocale: lang === "ta" ? "en_LK" : "ta_LK",
      images: [SHARE_IMAGE],
    },
    twitter: { card: "summary_large_image", title, description, images: [SHARE_IMAGE.url] },
  };
}
